  "ei.aato": "भवतः टर्नओवर",
  "ei.a.none": "न ज्ञातम् / न स्थापितम्",
  "ei.a.lt5": "2017-18 तः कस्मिन् अपि वर्षे ₹5 कोटितः अधिकं न",
  "ei.a.5to10": "कस्मिंश्चित् वर्षे ₹5 कोटितः अधिकम्, गतवर्षे ₹10 कोटितः न्यूनम्",
  "ei.a.10p": "₹10 कोटिः अथवा अधिकम्",
  "ei.h.aato": "अनेन निश्चीयते यत् ई-इनवॉइस भवते प्रवर्तते न वा, 30 दिनानां सीमा प्रवर्तते न वा। एतत् अस्मिन् एव ब्राउज़र-मध्ये स्मर्यते।",
  "ev.hsn6": "आइटम {n}: ई-इनवॉइस-मध्ये 6 अथवा 8 अङ्कानां HSN/SAC कोड आवश्यकम् (4 अङ्काः केवलं ₹5 कोटितः न्यून-व्यापाराणां कृते, ये ई-इनवॉइस न रचयन्ति)।",
  "ev.old30": "इदं इनवॉइस 30 अथवा अधिकदिनानि पुरातनम्। ₹10 कोटिः अथवा अधिक-टर्नओवर-सति पोर्टल इदम् इदानीं न पञ्जीकरोति। नूतनं इनवॉइस रचयितुं पूर्वं स्वस्य अकाउंटेंट पृच्छतु।",
  "ev.lt5": "ई-इनवॉइस भवतः कृते अनिवार्यं नास्ति, यावत् 2017-18 तः कस्मिंश्चित् वर्षे भवतः टर्नओवर ₹5 कोटिं न अतिक्रान्तवत्।",
  "ev.old180": "180 दिनेभ्यः अधिक-पुरातन-डॉक्यूमेंट-पत्रस्य ई-वे बिल पोर्टल न रचयति।",
  "ev.smallst": "{st} अन्तः ई-वे बिल सामान्यतः ₹{v} तः अधिके एव आवश्यकम् (अन्यराज्ये ₹50,000 तः अधिके; अन्यराज्यं गच्छतां जॉब-वर्क-हस्तशिल्पानां कृते सर्वेषु मूल्येषु आवश्यकम्)।",
  "ev.fromirn": "यदि भवतः व्यापारेण ई-इनवॉइस रचनीयम्, तर्हि अस्य इनवॉइस-स्य ई-वे बिल पोर्टल केवलं अस्य IRN तः रचयति: “ई-इनवॉइस-सह ई-वे बिल अपि रचयतु” इत्यत्र टिक् करोतु, ई-इनवॉइस फ़ाइल रचयतु च।",
  "ev.tidchk": "ट्रांसपोर्टर ID इत्यस्य अन्तिमम् अक्षरं न मिलति। टङ्कण-दोषः अस्ति वा इति एकवारं परीक्षताम्।",
  "ei.rmnote": "यदि भवता एषः IRN पोर्टल-उपरि निरस्तः, तर्हि एषः इनवॉइस-क्रमाङ्कः पुनः कदापि न पञ्जीक्रियते। शुद्धं इनवॉइस नूतन-क्रमाङ्केन रचयतु।",
  /* tax rule fixes, bills (4 Nov 2026) */
