  "v.b2c": "GSTIN-रहित-ग्राहकाय ₹50,000 अथवा अधिक-बिल-पत्रे GST-नियमानुसारं ग्राहकस्य नाम, सङ्केतः, राज्यं च आवश्यकानि।",
  "c.r28": "1 फरवरी 2026 तः 28% GST अपाकृतम् (तानि वस्तूनि इदानीं 40% अथवा 18% मध्ये)। तथापि 28% सह सेव् करोतु?",
  "c.cash2l": "आयकर-विधौ एकस्य बिल-पत्रस्य कृते ₹2 लक्षम् अथवा अधिकं नगदं ग्रहीतुं निषिद्धम् (दण्डः तावत् एव)। तथापि सेव् करोतु?",
