  "v.orig": "अयं नोट यस्य इनवॉइस-कृते, तस्य नंबर दिनाङ्कं च लिखतु। GST-नियमानुसारं नोट-पत्रे एते आवश्यके।",
  "v.naddr": "GSTIN-रहितस्य ग्राहकस्य सङ्केतं राज्यं च लिखतु।",
  "c.cn30": "अस्य क्रेडिट नोट-पत्रस्य दिनाङ्कः तस्य इनवॉइस-इत्यस्य फ़ाइनेंशियल ईयर-समाप्तेः अनन्तरं 30 नवम्बर-तः परम् अस्ति (अथवा तस्य वर्षस्य एनुअल रिटर्न-फ़ाइलिंग-अनन्तरम्, यदि तत् पूर्वम्)। तस्मात् दिनाङ्कात् परं तस्य GST न्यूनीकर्तुं न शक्यते (व्यापार-डॉक्यूमेंट-रूपेण नोट वैधम् एव)। तथापि सेव करोतु?",
