  "app.made": "निर्मितम्: {x}",
  "app.local": "डेटा होम न उद्घाटितम्, अतः केवलम् अस्मिन् साइट मध्ये अस्मिन् ब्राउज़र मध्ये सेव अस्ति। अग्रिमवारं डेटा होम प्रति गमिष्यति।",
  "app.vault": "अस्य ब्राउज़र इत्यस्य डेटा होम मध्ये सेव अस्ति, यत् Nivesh Sahayak इत्यस्य सर्वेषु टूल मध्ये साझा अस्ति। अस्मभ्यं किमपि न प्रेष्यते।",
  "app.help": "एतत् कथं कार्यं करोति",
  "app.helpp": "billing., cash-memo., credit-note. इत्येतेषु निर्मितानि बिलानि अत्र स्वयं दृश्यन्ते। प्राप्तं दत्तं च धनम् अत्र लिखतु; ऐप तत् बिलैः सह योजयति, अग्रिमं रक्षति, शेषदेयं हस्तस्थं कैश च गणयति।",
  "app.invfix": "अत्र परिशोधितानि इनवॉइस बिलिंग साइट मध्ये अपि दत्तम् इति दृश्यन्ते।",
