  "g3.note": "CGST अधिनियमस्य धारा 49 नियमस्य 88A च अनुसारं सेट्-ऑफ्: प्रथमं IGST क्रेडिट् प्रयुज्यते, ततः CGST SGST/UTGST क्रेडिट्; CGST SGST क्रेडिट्-योः परस्परं प्रयोगः कदापि न; रिवर्स्-चार्ज्-टैक्स् नगदेन दीयते। अन्तिमं सेट्-ऑफ् पोर्टल् फाइल् समये करोति।",
