  "g3.w.rcmv": "वाउचर् {no}: रिवर्स्-चार्ज्-टैक्स् CGST + SGST रूपेण गृहीतः। आपूर्तिकर्ता अन्यस्मिन् राज्ये चेत् (IGST) बॉक्स्-प्रकोष्ठान् परिवर्तयतु।",
  "g3.w.nogstin": "{p}-तः क्रय-बिल् {no}-स्य आपूर्तिकर्तुः वैधः GSTIN नास्ति, अतः तस्य ITC GSTR-2B-मध्ये न दृश्येत।",
  "g3.w.2b": "बॉक्स् 4(A)(5)-मध्ये ITC भवतः रक्षितेभ्यः क्रय-बिल्-पत्रेभ्यः व्ययेभ्यः च आगच्छति। GSTR-2B-मध्ये यावत् दृश्यते तावदेव क्लेम् करोतु; तत् न्यूनं चेत् GSTR-2B-आङ्कं टङ्कयतु।",
