  "g2.h.diff": "उभयत्र प्राप्तम्, परन्तु आङ्काः भिन्नाः। आपूर्तिकर्तुः सह बिल् परीक्षताम्; GSTR-2B यावत् दर्शयति तावदेव क्लेम् करोतु।",
  "g2.h.numdiff": "समानः आपूर्तिकर्ता राशिः च, परन्तु बिल्-नंबर् भिन्नरूपेण लिखितः। प्रायः टङ्कन-भेदः: भवतः प्रविष्टिं सम्यक् करोतु।",
  "g2.h.only2b": "आपूर्तिकर्त्रा एतानि बिल्-पत्राणि सूचितानि, परन्तु भवतः पुस्तकेषु रक्षितानि न सन्ति। वस्तूनि सेवाः वा प्राप्ताः चेत् प्रविशतु, अन्यथा आपूर्तिकर्तारं सम्यक् कर्तुं वदतु।",
  "g2.h.onlybooks": "एतेषां दिनाङ्कानां भवतः बिल्-पत्राणि यानि आपूर्तिकर्त्रा अद्यापि न सूचितानि। GSTR-2B-मध्ये यावत् न दृश्यन्ते तावत् ITC क्लेम् मा करोतु; आपूर्तिकर्तारं स्मारयतु।",
  "g2.h.noitc": "यत्र पोर्टल् ITC उपलब्धं नास्ति इति दर्शयति तानि बिल्-पत्राणि (यथा आपूर्ति-स्थानं आपूर्तिकर्तुः राज्ये, अथवा समय-सीमा)।",
