  "td.nopan": "वैध-PAN विना दरः 20% अथवा सामान्य-दरस्य द्विगुणः, यत् अधिकं (वस्तु-क्रये 5%)। प्राप्तकर्तारं PAN पृच्छतु।",
  "td.trans": "यः परिवहनकर्ता 10 अथवा न्यूनान् माल-वाहनान् धारयति PAN-सहितं घोषणां च ददाति तं TDS विना दातुं शक्यते।",
  "td.q": "गतवर्षे भवतः टर्नओवर् ₹10 करोडतः अधिकः आसीत् चेदेव कर्तयतु, तथा च अस्मात् विक्रेतुः वर्षस्य क्रयाणां ₹50 लक्षतः अधिकस्य भागस्य उपरि एव।",
  "td.ib": "टैक्स्-ऑडिट्-अधीनं न इति व्यक्तिना दत्ते किराये TDS एकवारं कर्त्यते, वर्षस्य अथवा किराया-अवधेः अन्तिम-मासस्य किरायातः।",
  "td.oldnote": "1 अप्रैल 2026 पूर्वं भुक्तिषु Income-tax Act, 1961 प्रवर्तते: पुरातनं धारा-संख्याम् उपयुञ्जीतु।",
