  "br.starth": "यस्य मासस्य परीक्षणं करणीयं तस्य स्टेटमेंट नेट-बैंकिंगतः Excel अथवा CSV रूपेण डाउनलोड कृत्वा अत्र उद्घाटयतु। फाइल अस्मिन् एव ब्राउज़रे पठ्यते; किमपि अपलोड न भवति।",
  "br.s1": "स्टेटमेंट फाइलम् उद्घाटयतु, अथवा बैंक-पङ्क्तीः हस्तेन टाइप करोतु।",
  "br.s2": "समानराशियुक्ताः पङ्क्तयः भवतः सेव कृताभिः रसीदैः, पेमेंटैः, व्ययैः, नगदजमाभिः च सह मेल्यन्ते।",
