  "b2.farules": "मूल्यह्रासः कथं गण्यते",
  "b2.farule1": "लेखानां मूल्यह्रासः कम्पनी-अधिनियमः, 2013 इत्यस्य शेड्यूल् II अनुसारम्: प्रत्येकस्य सम्पत्ति-प्रकारस्य उपयोग-कालः निर्धारितः (यथा सङ्गणकम् 3 वर्षाणि, फर्नीचर् 10 वर्षाणि, प्लाण्ट्-यन्त्राणि 15 वर्षाणि, कार् 8 वर्षाणि), अवशिष्टमूल्यं प्रायः मूल्यस्य 5% तः अधिकं न, वर्षमध्ये योजितायां विक्रीतायां वा सम्पत्तौ केवलम् उपयोग-दिनानां मूल्यह्रासः। स्ट्रेट् लाइन् (SLM: प्रतिवर्षं समा राशिः) अथवा रिटन् डाउन् वैल्यू (WDV: अवशिष्टराशौ निश्चितः दरः) चिनोतु। स्वामिनः फर्म्-संस्थाः च प्रायः इमाम् एव पद्धतिम् अनुसरन्ति; निर्णयः भवतः लेखाकारस्य।",
  "b2.farule2": "आयकर-मूल्यह्रासः प्रत्येकस्य ब्लॉकस्य पृथक् गण्यते: ब्लॉक्-दरेण रिटन् डाउन् वैल्यू (यथा प्लाण्ट्-यन्त्राणि 15%, फर्नीचर् 10%, सङ्गणकानि 40%), वर्षे 180 दिनेभ्यः न्यूनम् उपयुक्तायां सम्पत्तौ अर्धदरः, विक्रय-धनं च ब्लॉकात् न्यूनीक्रियते। एतत् केवलम् आयकर-विवरणपत्राय, लेखेषु कदापि न योज्यते। पूरिताः दराः सामान्य-ब्लॉक्-दराः: स्व-लेखाकारेण निश्चिनोतु, विशेषतः 1 अप्रैल 2026 तः आयकर-अधिनियमः, 2025 अन्तर्गत-वर्षेभ्यः।",
  "b2.farule3": "यदा भवान् 'मूल्यह्रासं योजयतु' नुदति तदा एव मूल्यह्रासः लेखेषु गच्छति: वर्षस्य अन्तिम-दिनस्य (वर्षमध्ये अद्यतनस्य वा) जर्नल-प्रविष्टिः मूल्यह्रासं डेबिट् करोति प्रत्येकां सम्पत्तिं न्यूनीकरोति च। पश्चात् सम्पत्तिं परिवर्तयति चेत् पुनः योजयतु, केवलम् अन्तरं योज्यते।",
