  "hp.s.ded": "PF, ESI, व्यवसाय-करः, TDS, अन्याः कटौतयः च। बटनम् एताः स्वयं गणयितुं शक्नोति।",
  "hp.s.entries": "प्रत्येकः लघुः नगद-व्ययः टॉप-अप वा, एकैका पङ्क्तिः। चालू-शेषः मञ्जूषायां कियत् भवेत् इति दर्शयति।",
  "hp.a.home": "अद्यतनं दृश्यम्: प्राप्यं देयं च धनम्, अवशिष्ट-बिलानि, नूतन-प्रविष्टयः च।",
  "hp.a.sales": "प्रत्येकः विक्रयः, प्रत्येकस्मिन् बिले कियत् अवशिष्टम्। कोटेशन आदेशं वा अत्रैव बिले परिवर्तयतु।",
  "hp.a.buy": "क्रय-बिलानि, प्रत्यागमनानि, व्ययाः च। अदत्तानि Dues मध्ये दृश्यन्ते।",
  "hp.a.money": "आगतं गतं च धनम्। प्रत्येकं पेमेंट् तस्य बिलैः सह योजयतु; अवशिष्टं पुरातनतमेषु बिलेषु गच्छति।",
